'use strict';

// MODULES //

var isValidGlyph = require( './utils/is-valid-glyph.js' );
var isValidRowCol = require( './utils/is-valid-row-col.js' );

/**
* Method to draw the bar.
*
* @private
* @name setGlyph
* @param {number} row - row number
* @param {number} col - col number
* @param {string} glyph - glyph name
* @param {boolean} overwrite - overwrite
* @returns {void}
*/
function setGlyph( row, col, glyph, overwrite ) {
	var a;
	var b;

	a = ( isValidRowCol( row, col, this._height, this._widht ) && isValidGlyph( glyph ) );

	// If color is already set to default we can change it
	b = ( overwrite || this._glyphMatrix[ row ][ col ] === this._glyph );
	if ( a && b ) {
		this._glyphMatrix[ row ][ col ] = glyph;
	}
}

module.exports = setGlyph;
